<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { agentApi } from '../api/agents'
import { delegationApi } from '../api/delegations'
import { fmtTime } from '../composables/format'
import { notify } from '../composables/toast'
import Modal from '../components/Modal.vue'
import Panel from '../components/Panel.vue'
import BaseSelect from '../components/BaseSelect.vue'

const agents = ref([]); const rows = ref([]); const loading = ref(false); const dlg = reactive({ open: false, saving: false, error: '' }); const form = reactive({ agentId: '', resource: '', actionText: '', resourceScope: '*', expiresAt: '' }); const pending = ref(null); const changing = ref(false)
const activeAgents = computed(() => agents.value.filter(a => a.status === 'ACTIVE'))
function agentName(id) { return agents.value.find(a => a.id === id)?.name || id }
function defaultExpiry() { const d = new Date(Date.now() + 2 * 3600000); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}T${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}` }
async function load() { loading.value = true; try { await Promise.all([agentApi.list().then(v => { agents.value = v || [] }), delegationApi.list().then(v => { rows.value = v || [] })]) } catch (e) { notify.err(e.message) } finally { loading.value = false } }
onMounted(load)
function openCreate() { Object.assign(form, { agentId: activeAgents.value[0]?.id || '', resource: '', actionText: '', resourceScope: '*', expiresAt: defaultExpiry() }); Object.assign(dlg, { open: true, saving: false, error: '' }) }
async function save() { dlg.error = ''; const actions = form.actionText.split(',').map(s => s.trim()).filter(Boolean); if (!form.agentId || !form.resource.trim() || !actions.length || !form.resourceScope.trim() || !form.expiresAt) return (dlg.error = '请填写所有必填项'); dlg.saving = true; try { await delegationApi.create({ agentId: form.agentId, resource: form.resource.trim(), actions, resourceScope: form.resourceScope.trim(), expiresAt: `${form.expiresAt}:00` }); notify.ok('委托已创建'); dlg.open = false; await load() } catch (e) { dlg.error = e.message } finally { dlg.saving = false } }
async function changeStatus() { changing.value = true; const restoring = pending.value.action === 'restore'; try { await (restoring ? delegationApi.restore(pending.value.id) : delegationApi.revoke(pending.value.id)); notify.ok(restoring ? '委托已恢复' : '委托已撤销'); pending.value = null; await load() } catch (e) { notify.err(e.message); pending.value = null } finally { changing.value = false } }
</script>

<template><Panel title="委托授权" subtitle="控制 Agent 代表你访问资源的范围和有效期"><template #actions><button class="btn" :disabled="loading" @click="load">↻ 刷新</button><button class="btn primary" :disabled="!activeAgents.length" @click="openCreate">＋ 新建委托</button></template>
  <table class="tbl"><thead><tr><th>智能体</th><th>资源</th><th>动作</th><th>范围</th><th>有效期</th><th>状态</th><th class="ops-h">操作</th></tr></thead><tbody><tr v-for="d in rows" :key="d.id"><td class="pname">{{ agentName(d.agentId) }}</td><td class="mono">{{ d.resource }}</td><td><span v-for="a in d.actions" :key="a" class="tag violet action-tag">{{ a }}</span></td><td class="mono">{{ d.resourceScope }}</td><td class="mono muted">{{ fmtTime(d.expiresAt) }}</td><td><span class="tag" :class="d.status === 'ACTIVE' ? 'ok' : 'off'"><span class="dot"></span>{{ d.status === 'ACTIVE' ? '有效' : d.status === 'REVOKED' ? '已撤销' : '已过期' }}</span></td><td><div class="ops"><button v-if="d.status === 'ACTIVE'" class="btn sm danger" @click="pending = { ...d, action: 'revoke' }">撤销</button><button v-else-if="d.status === 'REVOKED'" class="btn sm success" @click="pending = { ...d, action: 'restore' }">恢复</button></div></td></tr></tbody></table><div v-if="!rows.length" class="empty">{{ loading ? '正在加载…' : '暂无数据' }}</div>
</Panel><Modal v-if="dlg.open" title="新建委托" width="500px" @close="dlg.open = false"><form id="delegation-form" novalidate @submit.prevent="save"><div class="field"><label>Agent<span class="req">*</span></label><BaseSelect v-model="form.agentId" :options="activeAgents.map(a => ({ value: a.id, label: `${a.name} · ${a.tenantId}` }))" placeholder="请选择 Agent" /></div><div class="field"><label>资源<span class="req">*</span></label><input v-model="form.resource" class="input mono" maxlength="128" placeholder="project-report" /></div><div class="field"><label>动作<span class="req">*</span></label><input v-model="form.actionText" class="input mono" placeholder="read,export" /><small class="muted">多个动作以逗号分隔</small></div><div class="field"><label>资源范围<span class="req">*</span></label><input v-model="form.resourceScope" class="input mono" maxlength="512" placeholder="project-123 或 *" /></div><div class="field"><label>有效期至<span class="req">*</span></label><input v-model="form.expiresAt" type="datetime-local" class="input" /></div><div v-if="dlg.error" class="err-line" role="alert">⚠ {{ dlg.error }}</div></form><template #footer><button class="btn" @click="dlg.open = false">取消</button><button class="btn primary" type="submit" form="delegation-form" :disabled="dlg.saving">{{ dlg.saving ? '创建中…' : '创建委托' }}</button></template></Modal><Modal v-if="pending" :title="pending.action === 'restore' ? '确认恢复委托' : '确认撤销委托'" width="400px" @close="pending = null"><p class="lead">确定{{ pending.action === 'restore' ? '恢复' : '撤销' }} Agent <b>{{ agentName(pending.agentId) }}</b> 的这条委托吗？</p><p class="muted">{{ pending.action === 'restore' ? '恢复后将在有效期内重新允许对应工具调用。' : '撤销后授权检查将立即拒绝该委托。' }}</p><template #footer><button class="btn" @click="pending = null">取消</button><button class="btn" :class="pending.action === 'restore' ? 'success' : 'danger'" :disabled="changing" @click="changeStatus">{{ changing ? '处理中…' : pending.action === 'restore' ? '确认恢复' : '确认撤销' }}</button></template></Modal></template>

<style scoped>.pname { font-weight: 600; }.action-tag { margin-right: 5px; }.lead { line-height: 1.8; margin-bottom: 8px; }</style>
